 const sourceLink=selected.job?'kitchen-flow.html?'+new URLSearchParams({outlet:selected.job.orders[0].outlet,stage:'demand',returnTo:location.href}):href('recipe-cost-editor.html',{item:req.recipe?.kitchenOriginalName||req.recipe?.name||req.name,cat:selected.cat,i:selected.i,qty:req.qty||'',...(req.isSide&&extraNeeded()?{extraSides:extraChoice()===true?'yes':extraChoice()===false?'no':'pending'}:{})});
